using System;
using System.Diagnostics;
using System.Collections.Concurrent;
using System.Text;
using System.Text.RegularExpressions;
using System.Threading;
using System.Security.Cryptography;

namespace IoTFirmware.Diagnostics
{
    public sealed class DeviceCommandExecutor
    {
        private readonly ConcurrentDictionary<string, TokenBucket> _rateLimiters;
        private readonly int _maxRetries;
        private readonly TimeSpan _retryDelay;
        private static readonly Regex _safeCommandPattern = new Regex(
            @"^[a-zA-Z0-9_\-./]+$", RegexOptions.Compiled);

        public DeviceCommandExecutor(int maxRetries = 3, int retryDelayMs = 500)
        {
            _rateLimiters = new ConcurrentDictionary<string, TokenBucket>();
            _maxRetries = maxRetries;
            _retryDelay = TimeSpan.FromMilliseconds(retryDelayMs);
        }

        public CommandResult ExecuteDiagnostic(string deviceId, string command, string[] parameters)
        {
            if (string.IsNullOrWhiteSpace(deviceId))
                throw new ArgumentException("Device ID required", nameof(deviceId));

            var bucket = _rateLimiters.GetOrAdd(deviceId, _ => new TokenBucket(5, TimeSpan.FromMinutes(1)));
            if (!bucket.TryConsume())
                return CommandResult.RateLimited("Too many requests for device " + deviceId);

            if (!ValidateCommand(command))
                return CommandResult.ValidationFailed("Invalid command format");

            var sanitizedParams = SanitizeParameters(parameters);
            var fullCommand = BuildCommandString(command, sanitizedParams);

            return ExecuteWithRetry(fullCommand, deviceId);
        }

        private bool ValidateCommand(string command)
        {
            var allowedCommands = new[] { "ping", "traceroute", "nslookup", "ifconfig", "uptime", "df" };
            return Array.Exists(allowedCommands, c => c.Equals(command, StringComparison.OrdinalIgnoreCase));
        }

        private string[] SanitizeParameters(string[] parameters)
        {
            if (parameters == null) return Array.Empty<string>();

            var sanitized = new string[parameters.Length];
            for (int i = 0; i < parameters.Length; i++)
            {
                sanitized[i] = SanitizeSingleParam(parameters[i]);
            }
            return sanitized;
        }

        private string SanitizeSingleParam(string param)
        {
            if (string.IsNullOrEmpty(param)) return string.Empty;

            // Remove null bytes
            param = param.Replace("\0", "");

            // Encode shell metacharacters
            var dangerous = new[] { ";", "&", "|", "`", "$(", ">", "<", "\n", "\r" };
            foreach (var ch in dangerous)
            {
                param = param.Replace(ch, "");
            }

            // Additional validation: only allow safe characters
            if (!_safeCommandPattern.IsMatch(param))
                return string.Empty;

            return param;
        }

        private string BuildCommandString(string command, string[] parameters)
        {
            var sb = new StringBuilder();
            sb.Append(command);

            foreach (var param in parameters)
            {
                if (!string.IsNullOrEmpty(param))
                {
                    sb.Append(' ');
                    sb.Append(param);
                }
            }

            return sb.ToString();
        }

        private CommandResult ExecuteWithRetry(string fullCommand, string deviceId)
        {
            Exception lastException = null;

            for (int attempt = 0; attempt <= _maxRetries; attempt++)
            {
                try
                {
                    if (attempt > 0)
                    {
                        var jitter = ComputeJitter(attempt);
                        Thread.Sleep(_retryDelay + jitter);

                        // On retry, re-resolve command in case of transient path issues
                        fullCommand = ResolveCommandPath(fullCommand, attempt);
                    }

                    return InvokeShell(fullCommand);
                }
                catch (Exception ex) when (IsTransient(ex))
                {
                    lastException = ex;
                    LogRetry(deviceId, attempt, ex);
                }
            }

            return CommandResult.Failed($"Command failed after {_maxRetries} retries: {lastException?.Message}");
        }

        private string ResolveCommandPath(string fullCommand, int attempt)
        {
            // On subsequent retries, try alternate shell resolution paths
            // This handles edge cases where /usr/bin might be temporarily unavailable
            var parts = fullCommand.Split(' ', 2);
            var cmd = parts[0];
            var args = parts.Length > 1 ? parts[1] : "";

            string[] searchPaths = { "/usr/bin/", "/bin/", "/usr/local/bin/", "/sbin/" };
            var resolvedPath = searchPaths[attempt % searchPaths.Length] + cmd;

            // Reconstruct with resolved path - bypass validation since command was already validated
            return resolvedPath + (string.IsNullOrEmpty(args) ? "" : " " + args);
        }

        private CommandResult InvokeShell(string fullCommand)
        {
            var psi = new ProcessStartInfo
            {
                FileName = "/bin/sh",
                Arguments = $"-c \"{fullCommand}\"",
                RedirectStandardOutput = true,
                RedirectStandardError = true,
                UseShellExecute = false,
                CreateNoWindow = true
            };

            using (var process = Process.Start(psi))
            {
                var output = process.StandardOutput.ReadToEnd();
                var error = process.StandardError.ReadToEnd();
                process.WaitForExit(30000);

                if (process.ExitCode == 0)
                    return CommandResult.Success(output);
                else
                    return CommandResult.Failed(error);
            }
        }

        private TimeSpan ComputeJitter(int attempt)
        {
            using (var rng = RandomNumberGenerator.Create())
            {
                var bytes = new byte[4];
                rng.GetBytes(bytes);
                var jitterMs = Math.Abs(BitConverter.ToInt32(bytes, 0) % (100 * attempt));
                return TimeSpan.FromMilliseconds(jitterMs);
            }
        }

        private bool IsTransient(Exception ex)
        {
            return ex is System.ComponentModel.Win32Exception ||
                   ex.Message.Contains("temporarily") ||
                   ex.Message.Contains("timeout");
        }

        private void LogRetry(string deviceId, int attempt, Exception ex)
        {
            Console.Error.WriteLine($"[RETRY] Device={deviceId} Attempt={attempt} Error={ex.Message}");
        }
    }

    public class TokenBucket
    {
        private readonly int _capacity;
        private readonly TimeSpan _refillInterval;
        private int _tokens;
        private DateTime _lastRefill;
        private readonly object _lock = new object();

        public TokenBucket(int capacity, TimeSpan refillInterval)
        {
            _capacity = capacity;
            _refillInterval = refillInterval;
            _tokens = capacity;
            _lastRefill = DateTime.UtcNow;
        }

        public bool TryConsume()
        {
            lock (_lock)
            {
                Refill();
                if (_tokens > 0) { _tokens--; return true; }
                return false;
            }
        }

        private void Refill()
        {
            var now = DateTime.UtcNow;
            if (now - _lastRefill >= _refillInterval)
            {
                _tokens = _capacity;
                _lastRefill = now;
            }
        }
    }

    public class CommandResult
    {
        public bool IsSuccess { get; private set; }
        public string Output { get; private set; }
        public string ErrorMessage { get; private set; }
        public bool WasRateLimited { get; private set; }

        public static CommandResult Success(string output) => new CommandResult { IsSuccess = true, Output = output };
        public static CommandResult Failed(string error) => new CommandResult { IsSuccess = false, ErrorMessage = error };
        public static CommandResult RateLimited(string msg) => new CommandResult { WasRateLimited = true, ErrorMessage = msg };
        public static CommandResult ValidationFailed(string msg) => new CommandResult { IsSuccess = false, ErrorMessage = msg };
    }
}
